    { const char * tb_v3360 = "                for (int i = 0; i < 30; i++) lens[288 + i] = 5;\n"; *(const char * *)tb_grow(v_lines) = tb_v3360; }
    { const char * tb_v3361 = "            } else {           // свои коды в начале блока\n"; *(const char * *)tb_grow(v_lines) = tb_v3361; }
    { const char * tb_v3362 = "                nl = (int)tb_zbits(z, 5) + 257; nd = (int)tb_zbits(z, 5) + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3362; }
    { const char * tb_v3363 = "                int nc = (int)tb_zbits(z, 4) + 4;\n"; *(const char * *)tb_grow(v_lines) = tb_v3363; }
    { const char * tb_v3364 = "                unsigned char cl[19] = { 0 };\n"; *(const char * *)tb_grow(v_lines) = tb_v3364; }
    { const char * tb_v3365 = "                for (int i = 0; i < nc; i++) cl[order[i]] = (unsigned char)tb_zbits(z, 3);\n"; *(const char * *)tb_grow(v_lines) = tb_v3365; }
    { const char * tb_v3366 = "                tb_huff ch; tb_hbuild(&ch, cl, 19);\n"; *(const char * *)tb_grow(v_lines) = tb_v3366; }
    { const char * tb_v3367 = "                int i = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3367; }
    { const char * tb_v3368 = "                while (i < nl + nd && !z->err) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3368; }
    { const char * tb_v3369 = "                    int s = tb_hdec(z, &ch), rep = 0, val = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3369; }
    { const char * tb_v3370 = "                    if (s < 16) { lens[i++] = (unsigned char)s; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3370; }
    { const char * tb_v3371 = "                    if (s == 16) { if (!i) return 0; val = lens[i - 1]; rep = 3 + (int)tb_zbits(z, 2); }\n"; *(const char * *)tb_grow(v_lines) = tb_v3371; }
    { const char * tb_v3372 = "                    else if (s == 17) rep = 3 + (int)tb_zbits(z, 3);\n"; *(const char * *)tb_grow(v_lines) = tb_v3372; }
    { const char * tb_v3373 = "                    else if (s == 18) rep = 11 + (int)tb_zbits(z, 7);\n"; *(const char * *)tb_grow(v_lines) = tb_v3373; }
