    { const char * tb_v3636 = "// ---------- Vulkan (Linux и Windows) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3636; }
    { const char * tb_v3637 = "// Свои описания Vulkan (только то, что нужно): программе не нужны заголовки Vulkan,\n"; *(const char * *)tb_grow(v_lines) = tb_v3637; }
    { const char * tb_v3638 = "// а сама библиотека Vulkan грузится при запуске (dlopen) — нет её, рисуем на процессоре.\n"; *(const char * *)tb_grow(v_lines) = tb_v3638; }
