    { const char * tb_v4989 = "    // как у экрана: видеокарта сама ждёт обновления экрана (60 Гц — 60 кадров, 120 Гц — 120);\n"; *(const char * *)tb_grow(v_lines) = tb_v4989; }
    { const char * tb_v4990 = "    // кадр пришёл быстрее 4 мс — экран частоту не держит, держим сами 60 кадров в секунду\n"; *(const char * *)tb_grow(v_lines) = tb_v4990; }
    { const char * tb_v4991 = "    else if (!tb_gpu_on || now - tb_last_us < 4000) period = 16667;\n"; *(const char * *)tb_grow(v_lines) = tb_v4991; }
    { const char * tb_v4992 = "    if (period && now - tb_last_us < period) { usleep((useconds_t)(period - (now - tb_last_us))); now = tb_time_us(); }\n"; *(const char * *)tb_grow(v_lines) = tb_v4992; }
    { const char * tb_v4993 = "    tb_frame_ms_v = (now - tb_last_us + 500) / 1000;\n"; *(const char * *)tb_grow(v_lines) = tb_v4993; }
    { const char * tb_v4994 = "    tb_last_us = now;\n"; *(const char * *)tb_grow(v_lines) = tb_v4994; }
    { const char * tb_v4995 = "    if (!tb_fps_t0) tb_fps_t0 = now;\n"; *(const char * *)tb_grow(v_lines) = tb_v4995; }
    { const char * tb_v4996 = "    tb_fps_n++;\n"; *(const char * *)tb_grow(v_lines) = tb_v4996; }
