    { const char * tb_v4998 = "    tb_last_frame = now / 1000;\n"; *(const char * *)tb_grow(v_lines) = tb_v4998; }
    { const char * tb_v4999 = "    return !tb_gclosed;\n"; *(const char * *)tb_grow(v_lines) = tb_v4999; }
    { const char * tb_v5000 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5000; }
